-- 429 (données, appliquées le 15/10/2026) — Feuilles de préparation des sacs (PDF de l'équipe) = SOURCE DE VÉRITÉ (décision
-- d'Oïhan) : bien_sac_preparation (36 sacs, 6 sans bien), bien_lit déduits des draps (King / Queen / Twin), fiche AE
-- (bien_toolbox linge_plat / linge_eponge / consommables) remplacée par le contenu du PDF — anciennes valeurs dans
-- fiche_historique (trigger trg_historique_bien_toolbox). DUL et CERES : 2 sacs aux produits différents → produits non appliqués.
-- Script générateur : transcription fidèle du PDF (scratchpad sacs.js).

-- BGH (annonce Hospitable : chambre verte queen 160, chambre terracotta king 180 ou 2 lits 90 ; fiche linge : draps King)
with b as (select id from bien where code = 'BGH'),
l1 as (insert into bien_lit (bien_id, piece, type, largeur_cm, linge, ordre, source, maj_par, note)
  select id, 'Chambre verte', 'queen', 160, 'King', 1, 'migration', 'migration 429', 'Annonce : queen-size 160×200 (fiche linge : draps King)' from b where not exists (select 1 from bien_lit x where x.bien_id = b.id) returning id),
l2 as (insert into bien_lit (bien_id, piece, type, largeur_cm, linge, transforme_type, transforme_nombre, transforme_largeur_cm, transforme_linge, ordre, source, maj_par, note)
  select id, 'Chambre terracotta', 'king', 180, 'King', 'simple', 2, 90, 'Twin', 2, 'migration', 'migration 429', 'Annonce : king 180×200 ou 2 lits 90×200 (préparé en king sans demande)' from b where not exists (select 1 from bien_lit x where x.bien_id = b.id) returning id)
insert into bien_couchage (bien_id, nom, lits, ordre, maj_par)
select b.id, '2 grands lits', jsonb_build_array(jsonb_build_object('lit_id', l1.id, 'mode', 'normal'), jsonb_build_object('lit_id', l2.id, 'mode', 'normal')), 1, 'migration 429' from b, l1, l2
union all
select b.id, '1 grand lit + 2 petits lits', jsonb_build_array(jsonb_build_object('lit_id', l1.id, 'mode', 'normal'), jsonb_build_object('lit_id', l2.id, 'mode', 'transforme')), 2, 'migration 429' from b, l1, l2;

